                    child = build_node(e.path, opts)
                except OSError:
                    continue
                children.append(child)
                total += child.size
            children.sort(key=lambda n: (-n.size, n.name))
            node.children = children; node.size = total
    return node

def fmt_size(n, as_bytes=False):
    n = int(n)
    if as_bytes:
        return f"{n} B"
    units = [('GiB',1024**3), ('MiB',1024**2), ('KiB',1024)]
    for suf, val in units:
        if n >= val:
            return f"{n/val:.2f} {suf}"
    return f"{n} B"

def bar_len_for(size, max_size):
    if max_size <= 0 or size <= 0:
        return 0
    v = (int(size) * (BAR_WIDTH + 1)) // int(max_size) - 1
    if v < 0: v = 0
    if v > BAR_WIDTH: v = BAR_WIDTH
    return int(v)

def display_children(node, depth, opts):
    if opts.depth is not None and depth >= opts.depth:
        return []
    children = node.children
    if not children:
        return []
    if opts.aggr is None:
        return children
    kept = []
    agg_size = 0
    any_agg = False
    for c in children:
        if c.size < opts.aggr:
            agg_size += c.size; any_agg = True
        else:
            kept.append(c)
    if any_agg:
        kept = list(kept)
        kept.append(Node('<aggregated>', size=agg_size, self_size=agg_size, is_dir=False))
    return kept

def field_text(prefix, name):
    max_name = max(0, FIELD_WIDTH - len(prefix) - 1)
    s = prefix + name[:max_name]
    if len(s) < FIELD_WIDTH:
        s = s + ' ' * (FIELD_WIDTH - len(s))
    else:
        s = s[:FIELD_WIDTH-1] + ' '
    return s

def bar_field(n, ascii_mode):
    if n <= 0:
        return ' ' + (' ' * BAR_WIDTH)
    ch = '#' if ascii_mode else '█'
    return ' ' + (' ' * (BAR_WIDTH - n)) + (ch * n)

def render_node_lines(node, opts):
    print(f"[ {node.name} {fmt_size(node.size, opts.bytes)} ]")
    children = display_children(node, 0, opts)
    if not children:
        return
    max_size = max((c.size for c in children), default=0)
    for c in children:
        c.bar_len = bar_len_for(c.size, max_size)
    for idx, c in enumerate(children):
        render_child(c, opts, parent_size=node.size, depth=1, ancestors_last=[], is_last=(idx==len(children)-1), inherited_bar=c.bar_len)

def render_child(node, opts, parent_size, depth, ancestors_last, is_last, inherited_bar):
    parts = []
    for last in ancestors_last:
        parts.append('   ' if last else '│  ')
    parts.append('└─ ' if is_last else '├─ ')
    prefix = ''.join(parts)
    pct = 0 if parent_size <= 0 else int((node.size * 100) // parent_size)
    size_s = fmt_size(node.size, opts.bytes)
    # dutree's ASCII/no-color mode carries the top-level bar down the subtree.
    blen = inherited_bar
    print(f"{field_text(prefix, node.name)}│{bar_field(blen, opts.ascii)}│{pct:4d}%{size_s:>14}")
    children = display_children(node, depth, opts)
    if not children:
        return
    # Descendants inherit their top-level ancestor's bar length in -A output.
    for idx, c in enumerate(children):
        render_child(c, opts, parent_size=node.size, depth=depth+1,
                     ancestors_last=ancestors_last+[is_last],
                     is_last=(idx==len(children)-1), inherited_bar=inherited_bar)

def main():
    opts = parse_args(sys.argv)
    # Validate command-line paths with exists() to match top-level broken-symlink behavior.
    for p in opts.paths:
        if not os.path.exists(p):
            print(f"path {p} doesn't exist")
            return 1
    roots = []
    for p in opts.paths:
        try:
            roots.append(build_node(p, opts, root=True))
        except OSError:
            print(f"path {p} doesn't exist")
            return 1
    if len(roots) == 1:
        root = roots[0]
    else:
        root = Node('<collection>', size=sum(r.size for r in roots), self_size=0, is_dir=True, children=roots)
        root.children.sort(key=lambda n: (-n.size, n.name))
    render_node_lines(root, opts)
    return 0

if __name__ == '__main__':
    sys.exit(main())
